WITH "g1" AS (SELECT "t1"."branch_id" AS "branch_id", MAX("t1"."branch_name") AS "branch_id_label", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "net_revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."branch_id"), "g2" AS (SELECT "t1"."branch_id" AS "branch_id", MAX("t1"."branch_name") AS "branch_id_label", SUM(CASE WHEN "t0"."snapshot_date" = (SELECT MAX("s"."snapshot_date") FROM "sales"."stock_daily" AS "s" WHERE "s"."snapshot_date" >= DATE '2026-08-01' AND "s"."snapshot_date" < DATE '2026-09-01') THEN "t0"."qty" END) AS "closing_stock" FROM "sales"."stock_daily" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."snapshot_date" = (SELECT MAX("s"."snapshot_date") FROM "sales"."stock_daily" AS "s" WHERE "s"."snapshot_date" >= DATE '2026-08-01' AND "s"."snapshot_date" < DATE '2026-09-01')) GROUP BY "t1"."branch_id"), "spine" AS (SELECT "branch_id" FROM "g1" UNION SELECT "branch_id" FROM "g2") SELECT "spine"."branch_id" AS "branch_id", COALESCE("g1"."branch_id_label", "g2"."branch_id_label") AS "branch_id_label", "g1"."net_revenue" AS "net_revenue", "g2"."closing_stock" AS "closing_stock" FROM "spine" LEFT JOIN "g1" ON "g1"."branch_id" IS NOT DISTINCT FROM "spine"."branch_id" LEFT JOIN "g2" ON "g2"."branch_id" IS NOT DISTINCT FROM "spine"."branch_id" ORDER BY "net_revenue" DESC LIMIT 1000
